rollback.sql:
DELETE FROM krrg_grades
WHERE code IN ('JUNIOR', 'JUNIOR_PLUS', 'MIDDLE', 'MIDDLE_PLUS',
               'SENIOR', 'STAFF', 'PRINCIPAL', 'LEAD');

changeSet.sql:
-- 1. Проверяем, что целевые грейды существуют
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM krrg_grades WHERE code = 'JUNIOR_PLUS') THEN
        RAISE EXCEPTION 'JUNIOR_PLUS not found, cannot migrate links from JUNIOR+';
END IF;
    IF NOT EXISTS (SELECT 1 FROM krrg_grades WHERE code = 'MIDDLE_PLUS') THEN
        RAISE EXCEPTION 'MIDDLE_PLUS not found, cannot migrate links from MIDDLE+';
END IF;
END $$;

-- 2. Перепривязываем ссылки с JUNIOR+ на JUNIOR_PLUS
UPDATE krrg_vacancy_grade_link l
SET grade_id = new_grade.id
    FROM krrg_grades old_grade, krrg_grades new_grade
WHERE old_grade.code = 'JUNIOR+'
  AND new_grade.code = 'JUNIOR_PLUS'
  AND l.grade_id = old_grade.id
  AND NOT EXISTS (
    SELECT 1 FROM krrg_vacancy_grade_link l2
    WHERE l2.vacancy_id = l.vacancy_id
  AND l2.grade_id = new_grade.id
    );

-- 3. Удаляем оставшиеся ссылки на JUNIOR+
DELETE FROM krrg_vacancy_grade_link l
    USING krrg_grades old_grade
WHERE old_grade.code = 'JUNIOR+'
  AND l.grade_id = old_grade.id;

-- 4. Проверяем, что на JUNIOR+ больше нет ссылок
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM krrg_vacancy_grade_link l
        JOIN krrg_grades g ON g.id = l.grade_id
        WHERE g.code = 'JUNIOR+'
    ) THEN
        RAISE EXCEPTION 'Cannot delete JUNIOR+: still referenced by vacancy_grade_link';
END IF;
END $$;

-- 5. Удаляем JUNIOR+ из справочника
DELETE FROM krrg_grades WHERE code = 'JUNIOR+';

-- 6. Перепривязываем ссылки с MIDDLE+ на MIDDLE_PLUS
UPDATE krrg_vacancy_grade_link l
SET grade_id = new_grade.id
    FROM krrg_grades old_grade, krrg_grades new_grade
WHERE old_grade.code = 'MIDDLE+'
  AND new_grade.code = 'MIDDLE_PLUS'
  AND l.grade_id = old_grade.id
  AND NOT EXISTS (
    SELECT 1 FROM krrg_vacancy_grade_link l2
    WHERE l2.vacancy_id = l.vacancy_id
  AND l2.grade_id = new_grade.id
    );

-- 7. Удаляем оставшиеся ссылки на MIDDLE+
DELETE FROM krrg_vacancy_grade_link l
    USING krrg_grades old_grade
WHERE old_grade.code = 'MIDDLE+'
  AND l.grade_id = old_grade.id;

-- 8. Проверяем, что на MIDDLE+ больше нет ссылок
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM krrg_vacancy_grade_link l
        JOIN krrg_grades g ON g.id = l.grade_id
        WHERE g.code = 'MIDDLE+'
    ) THEN
        RAISE EXCEPTION 'Cannot delete MIDDLE+: still referenced by vacancy_grade_link';
END IF;
END $$;

-- 9. Удаляем MIDDLE+ из справочника
DELETE FROM krrg_grades WHERE code = 'MIDDLE+';

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM krrg_vacancy_grade_link l
        LEFT JOIN krrg_grades g ON g.id = l.grade_id
        WHERE g.id IS NULL
    ) THEN
        RAISE EXCEPTION 'Broken references found in krrg_vacancy_grade_link';
END IF;
END $$;

-- 1. Удаляем FK, которые ссылаются на старую таблицу
DO $$
DECLARE
r RECORD;
BEGIN
FOR r IN
SELECT conname, conrelid::regclass AS tbl
FROM pg_constraint
WHERE confrelid = 'krrg_vacancy_grades'::regclass
          AND contype = 'f'
    LOOP
        EXECUTE format('ALTER TABLE %s DROP CONSTRAINT IF EXISTS %I', r.tbl, r.conname);
END LOOP;
END $$;

-- 2. Удаляем битые ссылки (grade_id, которых нет в krrg_grades)
DELETE FROM krrg_vacancy_grade_link
WHERE grade_id NOT IN (SELECT id FROM krrg_grades);

-- 3. Создаём FK на krrg_grades, если его ещё нет
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'fk_vacancy_grade_link__grade'
    ) THEN
ALTER TABLE krrg_vacancy_grade_link
    ADD CONSTRAINT fk_vacancy_grade_link__grade
        FOREIGN KEY (grade_id) REFERENCES krrg_grades(id);
END IF;
END $$;

-- 4. Удаляем старую таблицу
DROP TABLE IF EXISTS krrg_vacancy_grades;

rollback.sql:
-- Откат невозможен: старая таблица удалена.
-- Если нужно восстановить, используйте бэкап.
SELECT 1;
